	        if (fontBackColor !== null) {
	            g2d.setBackground(fontBackColor);
	        } else {
	            g2d.setBackground(armyc2.c2sd.renderer.utilities.Color.white);
	        }
	        if (textColor === null)
	            textColor = tg.get_LineColor();
	        var direction = -1;
