	                        geoCoordBL = converter.PixelsToGeo(coordBL);

	                        north = converter.PixelsToGeo(north);
	                        south = converter.PixelsToGeo(south);
	                        east = converter.PixelsToGeo(east);
	                        west = converter.PixelsToGeo(west);
