	      //geometry
	      drawArray2.push({
	        type: "text",
	        text: this.options.headquartersElement,
	        x: 100,
	        y: bbox.y2 + 35,
	        textanchor: "middle",
	        fontsize: 35,
	        fontfamily: fontFamily,
	        fontweight: "bold",
	        fill: fontColor,
	        stroke: false
	      });
	      gbbox.y2 = bbox.y2 + 35;
